    def nearest(targets, ref):
        return min(targets, key=lambda t: (manhattan(ref, t), abs(t[0] - ref[0]), abs(t[1] - ref[1])))

    def farthest(cands, ref):
        return max(cands, key=lambda t: (manhattan(ref, t), t[0], t[1]))

    def center_target():
        if w and h:
